(() => {
  'use strict';

  const COURSE = {"units":[{"id":1,"title":"Gen Alpha","subtitle":"Digital life, identity, habits, and technology","grammarTitle":"The Present Continuous","grammar":{"why":"Use the Present Continuous for actions happening now, temporary situations, and definite future arrangements.","formula":"Subject + am / is / are + verb-ing","negative":"Subject + am / is / are + not + verb-ing","question":"Am / Is / Are + subject + verb-ing?","signals":["now","right now","at the moment","at present","today","this week","tonight","tomorrow","next Friday"],"traps":["Do not use the base verb after am/is/are: “She is study” ✗ → “She is studying” ✓.","For a fixed future arrangement, the Present Continuous can be used with a clear future time: “We are meeting tomorrow.”","Watch spelling: make → making, run → running, lie → lying."],"examples":[["Now","Maya is studying for her English test."],["Temporary","We are using a new classroom this week."],["Future arrangement","I am meeting my cousin tomorrow."]]},"videoId":"ojNJUpYOZ98","videoTitle":"English Grade 8 — Unit 1 / Lesson 1 — Al Kheta Educational","lessons":[["Understanding Gen Alpha","Learn who Gen Alpha are, how they use technology, and how digital habits shape daily life.",["generation","digital native","screen time","trend","identity"]],["Digital Natives & Technology","Explore the connection between young people and digital devices, apps, and online communication.",["device","app","connect","online","digital skills"]],["The Digital Bridge","Compare Gen Z and Gen Alpha and notice the digital habits they have in common.",["common","far apart","include","share","community"]],["Story: The Little Inventor","Follow a young inventor who learns to express ideas, ask permission, and make responsible choices.",["inventor","curious","permission","creative","fair"]],["Let's Talk","Practice giving opinions, agreeing politely, and talking about balanced screen time.",["opinion","balance","connect","respectful","offline"]]]},{"id":2,"title":"My Digital Footprint","subtitle":"Privacy, security, passwords, and safe online behavior","grammarTitle":"Present Simple: Active & Passive + Modal Passive","grammar":{"why":"Use the active voice when the doer matters. Use the passive voice when the action or receiver matters more, or the doer is unknown/unimportant.","formula":"Active: Subject + base verb / s-es-ies.  Passive: Object + am/is/are + past participle.","negative":"Active: do/does not + base verb. Passive: am/is/are not + past participle.","question":"Active: Do/Does + subject + base verb?  Passive: Am/Is/Are + object + past participle?","signals":["every day","usually","often","regularly","by people","by the website"],"traps":["After does/doesn’t, use the base verb: “Does he uses…” ✗ → “Does he use…” ✓.","Passive needs the past participle: “is protect” ✗ → “is protected” ✓.","With modals, use modal + be + past participle: “should be kept”."],"examples":[["Active","People create a digital trail."],["Passive","A digital trail is created by people."],["Modal passive","Your password should be kept secret."]]},"videoId":"RAZeyXvHxZs","videoTitle":"English Grade 8 — Unit 2 — My Digital Footprint — Al Kheta Educational","lessons":[["Online Privacy & Security","Understand privacy settings, secure accounts, trusted people, and online risks.",["privacy","secure","setting","account","stranger"]],["Protecting Your Data","Learn why strong passwords, careful sharing, and secure data matter.",["password","data","protect","private","access"]],["Managing Your Online Data","Understand digital traces, posts, profiles, and how online information stays connected.",["trace","profile","upload","stored","update"]],["Tips for Online Safety","Turn safety ideas into clear advice and responsible online habits.",["make sure","stay safe online","risk","permission","be careful"]],["Story: Chapter 2","Use the story to practice online-safety vocabulary, reading details, and grammar in context.",["guardian","hack","clue","software","scary"]]]},{"id":3,"title":"Facing Challenges","subtitle":"Courage, determination, obstacles, and problem-solving","grammarTitle":"Past Simple & Past Continuous","grammar":{"why":"Use Past Simple for finished past actions. Use Past Continuous for an action in progress at a particular past time or interrupted by a shorter action.","formula":"Past Simple: subject + past verb. Past Continuous: subject + was/were + verb-ing.","negative":"Past Simple: did not + base verb. Past Continuous: was/were not + verb-ing.","question":"Past Simple: Did + subject + base verb?  Past Continuous: Was/Were + subject + verb-ing?","signals":["yesterday","last week","ago","in the past","at 5 o’clock yesterday","while","when"],"traps":["After did/didn’t, use the base verb: “Did she went?” ✗ → “Did she go?” ✓.","A long background action can be Past Continuous while a short interrupting action is Past Simple.","Use was with I/he/she/it and were with you/we/they."],"examples":[["Finished action","Rana won the race yesterday."],["Action in progress","Rana was running at 5 p.m."],["Interrupted action","When the bell rang, we were studying."]]},"videoId":"5s4M5cYA0Y4","videoTitle":"English Grade 8 — Unit 3 — Facing Challenges — Al Kheta Educational","lessons":[["Overcoming Obstacles","Talk about obstacles and the actions people take to overcome them.",["challenge","obstacle","struggle","solution","impossible"]],["Determination & Courage","Learn language for bravery, effort, disappointment, and second chances.",["determination","courage","brave","discouraged","second chance"]],["Facing Traffic Challenges","Use problem-solving language around traffic, transport, and city movement.",["traffic jam","monorail","metro","public transportation","blocked"]],["The Power Of Facing Challenges","Understand how attitude, practice, and persistence can change outcomes.",["attitude","practice","improve","give up","victory"]],["Story: Chapter 3","Read the story chapter and use past-time language to describe events and actions.",["race","crowd","medal","cheer","training"]]]},{"id":4,"title":"Art and Expression","subtitle":"Creativity, artists, performance, and expression","grammarTitle":"Connectors: because, so, but, although","grammar":{"why":"Connectors show the relationship between ideas: reason, result, contrast, and stronger contrast.","formula":"because = reason • so = result • but = simple contrast • although = contrast in a dependent clause.","negative":"The connector itself does not change the tense; keep the sentence structure correct on both sides.","question":"Choose the connector that matches the relationship between the two ideas.","signals":["because","so","but","although"],"traps":["Do not normally use “because” and “so” together in the same basic sentence: “Because I was tired, I slept.” ✓","“Although” introduces a contrast: “Although it was difficult, he continued.”","“But” joins two contrasting main ideas: “It was difficult, but he continued.”"],"examples":[["Reason","I visited the gallery because I love art."],["Result","The painting was bright, so everyone noticed it."],["Contrast","Although the sculpture was heavy, it looked elegant."]]},"videoId":"IrKeKnTMyEM","videoTitle":"English Grade 8 — Unit 4 — Art and Expression — Al Kheta Educational","lessons":[["Forms of Art","Explore visual and performing arts, materials, and ways people express ideas.",["artwork","sculpture","gallery","performance","materials"]],["Exploring Art","Discuss imagination, emotions, artistic traditions, and different styles.",["imagination","creativity","style","emotion","tradition"]],["An Article About An Artist","Read about an artist and identify facts, achievements, and meaningful artistic choices.",["artist","article","exhibit","recognition","inspiration"]],["My Performance Review","Give a clear opinion about a performance and support it with reasons and contrasts.",["performance","review","engage","attractive","message"]],["Story 2: Chapter 1","Use story events and art vocabulary to build comprehension and discussion skills.",["curious","studio","exhibition","symbol","identity"]]]},{"id":5,"title":"Around the World","subtitle":"Cultures, landmarks, traditions, and travel","grammarTitle":"Comparatives & Superlatives","grammar":{"why":"Use comparatives to compare two things. Use superlatives to compare one thing with a group.","formula":"Short adjectives: adj + er + than / the + adj + est. Long adjectives: more/less + adj + than / the most/least + adj.","negative":"Use “less” for comparison and keep the adjective form correct: less interesting than.","question":"Use “Which is …?” or “What is the most …?” to ask comparison questions.","signals":["than","the … of","the … in","more","most","less","least"],"traps":["Do not say “more taller” ✗. Use “taller” or “more interesting,” depending on the adjective.","Remember irregular forms: good → better → the best; bad → worse → the worst.","Use “the” with a superlative: “the most impressive”."],"examples":[["Comparative","Cairo is larger than many Egyptian cities."],["Long adjective","This museum is more impressive than the old one."],["Superlative","Mount Fuji is one of the most famous landmarks in Japan."]]},"videoId":"t87eq-pfbtI","videoTitle":"English Grade 8 — Unit 5 — Around the World — Al Kheta Educational","lessons":[["Have you ever explored the world?","Talk about travel experiences, destinations, and unforgettable places.",["continent","culture","destination","landmark","unforgettable"]],["A Tour Around Cairo","Describe places in Cairo and practice travel language and organized tours.",["capital","tour guide","city center","Tahrir Square","guided tour"]],["Around the World In Four Amazing Places","Compare landmarks, places, and cultures using descriptive vocabulary.",["Japan","Morocco","Petra","Machu Picchu","Reykjavik"]],["Come Explore With Us","Use travel expressions to explain routes, experiences, and memorable moments.",["explore","adventure","hiking","glacier","trail"]],["Story 2: Chapter 2","Build reading and vocabulary skills through a travel-focused story chapter.",["mysterious","gateway","treasure","market","memories"]]]},{"id":6,"title":"Young Innovators","subtitle":"Ideas, inventions, impact, and perseverance","grammarTitle":"First & Second Conditional","grammar":{"why":"First Conditional talks about real or possible future situations. Second Conditional talks about unreal or imaginary situations and can give advice.","formula":"First: If + Present Simple, will + base verb. Second: If + Past Simple, would/could/might + base verb.","negative":"First: If it doesn’t work, we won’t give up. Second: If I were you, I wouldn’t stop.","question":"What will you do if…? / What would you do if…?","signals":["if","will","would","could","might","were you"],"traps":["Do not put “will” directly after if in the normal First Conditional: “If it rains, we will stay home.”","Second Conditional commonly uses past simple after if, even for unreal present/future situations.","For advice, use “If I were you, I would …”."],"examples":[["Real possibility","If I finish my project, I will show it to the class."],["Imaginary","If I had more time, I would build a robot."],["Advice","If I were you, I would keep trying."]]},"videoId":null,"videoTitle":"Search the Al Kheta Educational YouTube channel for Unit 6","lessons":[["Making Your Ideas Happen","Turn an idea into steps, test it, learn from feedback, and improve it.",["invention","steps","brainstorm","feedback","useful"]],["Inspiring Innovators","Learn about innovators, role models, achievements, and persistence.",["innovator","inspire","achievement","patience","role model"]],["A Man Of Impact","Explore how an individual can use knowledge and work to create positive impact.",["impact","professor","biomedical","sensors","civil engineering"]],["Writing a Biography","Organize facts about a person and use time words to build a clear biography.",["biography","born","university","officially","victory"]],["Story 2: Chapter 3","Use the story to connect innovation, problem-solving, and perseverance.",["difficulty","competition","secret","honor","difference"]]]}],"lessons":[{"unit":1,"lessons":[{"id":"u1l1","number":1,"title":"Understanding Gen Alpha","description":"Learn who Gen Alpha are, how they use technology, and how digital habits shape daily life.","focus":["generation","digital native","screen time","trend","identity"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 1 Understanding Gen Alpha"},{"id":"u1l2","number":2,"title":"Digital Natives & Technology","description":"Explore the connection between young people and digital devices, apps, and online communication.","focus":["device","app","connect","online","digital skills"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 1 Digital Natives & Technology"},{"id":"u1l3","number":3,"title":"The Digital Bridge","description":"Compare Gen Z and Gen Alpha and notice the digital habits they have in common.","focus":["common","far apart","include","share","community"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 1 The Digital Bridge"},{"id":"u1l4","number":4,"title":"Story: The Little Inventor","description":"Follow a young inventor who learns to express ideas, ask permission, and make responsible choices.","focus":["inventor","curious","permission","creative","fair"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 1 Story: The Little Inventor"},{"id":"u1l5","number":5,"title":"Let's Talk","description":"Practice giving opinions, agreeing politely, and talking about balanced screen time.","focus":["opinion","balance","connect","respectful","offline"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 1 Let's Talk"}]},{"unit":2,"lessons":[{"id":"u2l1","number":1,"title":"Online Privacy & Security","description":"Understand privacy settings, secure accounts, trusted people, and online risks.","focus":["privacy","secure","setting","account","stranger"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 2 Online Privacy & Security"},{"id":"u2l2","number":2,"title":"Protecting Your Data","description":"Learn why strong passwords, careful sharing, and secure data matter.","focus":["password","data","protect","private","access"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 2 Protecting Your Data"},{"id":"u2l3","number":3,"title":"Managing Your Online Data","description":"Understand digital traces, posts, profiles, and how online information stays connected.","focus":["trace","profile","upload","stored","update"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 2 Managing Your Online Data"},{"id":"u2l4","number":4,"title":"Tips for Online Safety","description":"Turn safety ideas into clear advice and responsible online habits.","focus":["make sure","stay safe online","risk","permission","be careful"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 2 Tips for Online Safety"},{"id":"u2l5","number":5,"title":"Story: Chapter 2","description":"Use the story to practice online-safety vocabulary, reading details, and grammar in context.","focus":["guardian","hack","clue","software","scary"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 2 Story: Chapter 2"}]},{"unit":3,"lessons":[{"id":"u3l1","number":1,"title":"Overcoming Obstacles","description":"Talk about obstacles and the actions people take to overcome them.","focus":["challenge","obstacle","struggle","solution","impossible"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 3 Overcoming Obstacles"},{"id":"u3l2","number":2,"title":"Determination & Courage","description":"Learn language for bravery, effort, disappointment, and second chances.","focus":["determination","courage","brave","discouraged","second chance"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 3 Determination & Courage"},{"id":"u3l3","number":3,"title":"Facing Traffic Challenges","description":"Use problem-solving language around traffic, transport, and city movement.","focus":["traffic jam","monorail","metro","public transportation","blocked"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 3 Facing Traffic Challenges"},{"id":"u3l4","number":4,"title":"The Power Of Facing Challenges","description":"Understand how attitude, practice, and persistence can change outcomes.","focus":["attitude","practice","improve","give up","victory"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 3 The Power Of Facing Challenges"},{"id":"u3l5","number":5,"title":"Story: Chapter 3","description":"Read the story chapter and use past-time language to describe events and actions.","focus":["race","crowd","medal","cheer","training"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 3 Story: Chapter 3"}]},{"unit":4,"lessons":[{"id":"u4l1","number":1,"title":"Forms of Art","description":"Explore visual and performing arts, materials, and ways people express ideas.","focus":["artwork","sculpture","gallery","performance","materials"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 4 Forms of Art"},{"id":"u4l2","number":2,"title":"Exploring Art","description":"Discuss imagination, emotions, artistic traditions, and different styles.","focus":["imagination","creativity","style","emotion","tradition"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 4 Exploring Art"},{"id":"u4l3","number":3,"title":"An Article About An Artist","description":"Read about an artist and identify facts, achievements, and meaningful artistic choices.","focus":["artist","article","exhibit","recognition","inspiration"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 4 An Article About An Artist"},{"id":"u4l4","number":4,"title":"My Performance Review","description":"Give a clear opinion about a performance and support it with reasons and contrasts.","focus":["performance","review","engage","attractive","message"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 4 My Performance Review"},{"id":"u4l5","number":5,"title":"Story 2: Chapter 1","description":"Use story events and art vocabulary to build comprehension and discussion skills.","focus":["curious","studio","exhibition","symbol","identity"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 4 Story 2: Chapter 1"}]},{"unit":5,"lessons":[{"id":"u5l1","number":1,"title":"Have you ever explored the world?","description":"Talk about travel experiences, destinations, and unforgettable places.","focus":["continent","culture","destination","landmark","unforgettable"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 5 Have you ever explored the world?"},{"id":"u5l2","number":2,"title":"A Tour Around Cairo","description":"Describe places in Cairo and practice travel language and organized tours.","focus":["capital","tour guide","city center","Tahrir Square","guided tour"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 5 A Tour Around Cairo"},{"id":"u5l3","number":3,"title":"Around the World In Four Amazing Places","description":"Compare landmarks, places, and cultures using descriptive vocabulary.","focus":["Japan","Morocco","Petra","Machu Picchu","Reykjavik"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 5 Around the World In Four Amazing Places"},{"id":"u5l4","number":4,"title":"Come Explore With Us","description":"Use travel expressions to explain routes, experiences, and memorable moments.","focus":["explore","adventure","hiking","glacier","trail"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 5 Come Explore With Us"},{"id":"u5l5","number":5,"title":"Story 2: Chapter 2","description":"Build reading and vocabulary skills through a travel-focused story chapter.","focus":["mysterious","gateway","treasure","market","memories"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 5 Story 2: Chapter 2"}]},{"unit":6,"lessons":[{"id":"u6l1","number":1,"title":"Making Your Ideas Happen","description":"Turn an idea into steps, test it, learn from feedback, and improve it.","focus":["invention","steps","brainstorm","feedback","useful"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 6 Making Your Ideas Happen"},{"id":"u6l2","number":2,"title":"Inspiring Innovators","description":"Learn about innovators, role models, achievements, and persistence.","focus":["innovator","inspire","achievement","patience","role model"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 6 Inspiring Innovators"},{"id":"u6l3","number":3,"title":"A Man Of Impact","description":"Explore how an individual can use knowledge and work to create positive impact.","focus":["impact","professor","biomedical","sensors","civil engineering"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 6 A Man Of Impact"},{"id":"u6l4","number":4,"title":"Writing a Biography","description":"Organize facts about a person and use time words to build a clear biography.","focus":["biography","born","university","officially","victory"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 6 Writing a Biography"},{"id":"u6l5","number":5,"title":"Story 2: Chapter 3","description":"Use the story to connect innovation, problem-solving, and perseverance.","focus":["difficulty","competition","secret","honor","difference"],"videoSearch":"الخطة التعليمية الثاني الإعدادي English Unit 6 Story 2: Chapter 3"}]}],"questions":[{"id":"u1q1","unit":1,"lesson":1,"question":"Look! Sara ____ a short video right now.","answers":["creates","is creating","created","create"],"correct":1,"explanation":"“right now” points to the Present Continuous."},{"id":"u1q2","unit":1,"lesson":1,"question":"We ____ our grandparents this Friday.","answers":["visit","visited","are visiting","visiting"],"correct":2,"explanation":"A definite future arrangement can use the Present Continuous."},{"id":"u1q3","unit":1,"lesson":1,"question":"They ____ online at the moment.","answers":["study","studied","are studying","studies"],"correct":2,"explanation":"“at the moment” signals an action happening now."},{"id":"u1q4","unit":1,"lesson":2,"question":"My brother ____ a digital project this week.","answers":["is doing","does","did","do"],"correct":0,"explanation":"“this week” describes a temporary activity."},{"id":"u1q5","unit":1,"lesson":2,"question":"Choose the correct sentence.","answers":["He is use a tablet.","He using a tablet.","He is using a tablet.","He uses now a tablet."],"correct":2,"explanation":"Present Continuous = is + verb-ing."},{"id":"u1q6","unit":1,"lesson":2,"question":"Which word best completes the sentence? “Gen Alpha use ____ to communicate online.”","answers":["devices","races","medals","galleries"],"correct":0,"explanation":"Devices are tools used for digital communication."},{"id":"u1q7","unit":1,"lesson":3,"question":"Gen Z and Gen Alpha have some things ____.","answers":["common","empty","blocked","secret"],"correct":0,"explanation":"“have in common” means share similarities."},{"id":"u1q8","unit":1,"lesson":3,"question":"They ____ emojis to express feelings online.","answers":["use","are using","used","uses"],"correct":1,"explanation":"The sentence describes an activity happening in the current context."},{"id":"u1q9","unit":1,"lesson":3,"question":"The internet can help people ____ with others far away.","answers":["connect","fail","reduce","hide"],"correct":0,"explanation":"“connect with” is the natural expression."},{"id":"u1q10","unit":1,"lesson":4,"question":"Amal was ____ about how machines work.","answers":["curious","blocked","permanent","quietly"],"correct":0,"explanation":"Curious means wanting to know more."},{"id":"u1q11","unit":1,"lesson":4,"question":"She asked for ____ before downloading the app.","answers":["permission","traffic","bronze","population"],"correct":0,"explanation":"Permission = being allowed to do something."},{"id":"u1q12","unit":1,"lesson":4,"question":"A person who invents something new is an ____.","answers":["inventor","emoji","athlete","tour guide"],"correct":0,"explanation":"Inventor matches the meaning."},{"id":"u1q13","unit":1,"lesson":5,"question":"“I think we need more balance.” This sentence expresses a ____.","answers":["fact","opinion","command","definition"],"correct":1,"explanation":"“I think” introduces an opinion."},{"id":"u1q14","unit":1,"lesson":5,"question":"Choose the best reply: “Too much screen time can be unhealthy.”","answers":["That’s true, but we need balance.","Yesterday at five.","It is a gallery.","I am bronze."],"correct":0,"explanation":"The reply respectfully agrees and adds a contrasting idea."},{"id":"u1q15","unit":1,"lesson":5,"question":"Right now, I ____ my phone before bed.","answers":["am putting away","put away","put away yesterday","will putting away"],"correct":0,"explanation":"“Right now” requires Present Continuous."},{"id":"u2q16","unit":2,"lesson":1,"question":"People ____ digital trails every day.","answers":["create","creates","are created","created"],"correct":0,"explanation":"Plural subject + base verb in the Present Simple active."},{"id":"u2q17","unit":2,"lesson":1,"question":"A digital trail ____ by many online actions.","answers":["create","creates","is created","are creating"],"correct":2,"explanation":"Passive Present Simple = is/are + past participle."},{"id":"u2q18","unit":2,"lesson":1,"question":"____ he check his privacy settings regularly?","answers":["Do","Does","Is","Are"],"correct":1,"explanation":"Use Does with he/she/it."},{"id":"u2q19","unit":2,"lesson":2,"question":"Strong passwords ____ to protect accounts.","answers":["use","are used","is used","used"],"correct":1,"explanation":"Passwords receive the action, so use passive voice."},{"id":"u2q20","unit":2,"lesson":2,"question":"Your personal data should ____ private.","answers":["keep","kept","be kept","be keeping"],"correct":2,"explanation":"Modal passive = should + be + past participle."},{"id":"u2q21","unit":2,"lesson":2,"question":"She ____ share her password with strangers.","answers":["doesn’t","isn’t","don’t","not"],"correct":0,"explanation":"Negative Present Simple with she = doesn’t + base verb."},{"id":"u2q22","unit":2,"lesson":3,"question":"Some photos ____ online regularly.","answers":["upload","are uploaded","is upload","uploaded"],"correct":1,"explanation":"Photos are plural and receive the action."},{"id":"u2q23","unit":2,"lesson":3,"question":"What ____ you usually post online?","answers":["are","do","does","is"],"correct":1,"explanation":"Wh-question with you in Present Simple uses do."},{"id":"u2q24","unit":2,"lesson":3,"question":"A profile is updated when new information ____.","answers":["is added","adds","are adding","add"],"correct":0,"explanation":"The information receives the action."},{"id":"u2q25","unit":2,"lesson":4,"question":"You should be careful ____ clicking unknown links.","answers":["at","with","on","by"],"correct":1,"explanation":"The common expression is “be careful with”."},{"id":"u2q26","unit":2,"lesson":4,"question":"Think before you ____ personal information.","answers":["share","shares","shared","sharing"],"correct":0,"explanation":"After “you”, use the base verb."},{"id":"u2q27","unit":2,"lesson":4,"question":"“Make sure your settings are private.” This is mainly ____.","answers":["advice","a biography","a comparison","a story ending"],"correct":0,"explanation":"The sentence gives a safety recommendation."},{"id":"u2q28","unit":2,"lesson":5,"question":"A stranger ____ given access to my account.","answers":["is not","are not","does not","not is"],"correct":0,"explanation":"Singular passive negative: is not + past participle."},{"id":"u2q29","unit":2,"lesson":5,"question":"Which sentence is passive?","answers":["People protect accounts.","People use strong passwords.","Strong passwords are used.","Users check settings."],"correct":2,"explanation":"The object/receiver is the focus in the passive sentence."},{"id":"u2q30","unit":2,"lesson":5,"question":"Choose the safest sentence.","answers":["Share your password with everyone.","Think before you share personal data.","Use the same easy password everywhere.","Accept every stranger’s request."],"correct":1,"explanation":"Thinking before sharing is a safe online habit."},{"id":"u3q31","unit":3,"lesson":1,"question":"Mariam ____ a difficult task yesterday.","answers":["faces","faced","was facing","is facing"],"correct":1,"explanation":"A finished past action with “yesterday” uses Past Simple."},{"id":"u3q32","unit":3,"lesson":1,"question":"We ____ the problem when the teacher arrived.","answers":["discussed","were discussing","discuss","are discussing"],"correct":1,"explanation":"The longer action in progress was Past Continuous."},{"id":"u3q33","unit":3,"lesson":1,"question":"When the race started, Ali ____ ready.","answers":["was","is","were","be"],"correct":0,"explanation":"Ali = singular, so “was”."},{"id":"u3q34","unit":3,"lesson":2,"question":"They ____ training at 6 p.m. yesterday.","answers":["were","was","were training","trained"],"correct":2,"explanation":"Past Continuous = were + verb-ing."},{"id":"u3q35","unit":3,"lesson":2,"question":"She ____ give up after the first failure.","answers":["didn’t","wasn’t","doesn’t","not"],"correct":0,"explanation":"Past Simple negative = didn’t + base verb."},{"id":"u3q36","unit":3,"lesson":2,"question":"____ you practice before the competition?","answers":["Did","Were","Was","Do"],"correct":0,"explanation":"Past Simple question starts with Did."},{"id":"u3q37","unit":3,"lesson":3,"question":"The road was ____ because of a traffic jam.","answers":["blocked","curious","creative","shiny"],"correct":0,"explanation":"Blocked = closed or unable to move through."},{"id":"u3q38","unit":3,"lesson":3,"question":"People use public ____ to move around the city.","answers":["transportation","sculpture","gallery","emojis"],"correct":0,"explanation":"Public transportation describes shared city transport."},{"id":"u3q39","unit":3,"lesson":3,"question":"The bus ____ while we were waiting.","answers":["arrived","was arriving","arrive","arrives"],"correct":0,"explanation":"The shorter completed event can be Past Simple."},{"id":"u3q40","unit":3,"lesson":4,"question":"Although the task was hard, she ____.","answers":["continued","continues","was continue","continue"],"correct":0,"explanation":"Past context + completed action = Past Simple."},{"id":"u3q41","unit":3,"lesson":4,"question":"Keep ____ even when the first attempt fails.","answers":["try","trying","tried","to trying"],"correct":1,"explanation":"“Keep” is followed by a gerund (verb-ing)."},{"id":"u3q42","unit":3,"lesson":4,"question":"A positive ____ can help you deal with difficulties.","answers":["attitude","tomb","password","continent"],"correct":0,"explanation":"Attitude = the way you think/feel about something."},{"id":"u3q43","unit":3,"lesson":5,"question":"While the athletes ____ , the crowd cheered.","answers":["ran","were running","run","are running"],"correct":1,"explanation":"“While” often introduces an action in progress."},{"id":"u3q44","unit":3,"lesson":5,"question":"When I heard the news, I ____ surprised.","answers":["was","were","am","be"],"correct":0,"explanation":"I + was in Past Simple."},{"id":"u3q45","unit":3,"lesson":5,"question":"The team won a ____ medal.","answers":["gold","digital","private","natural"],"correct":0,"explanation":"Gold, silver, and bronze are medal types."},{"id":"u4q46","unit":4,"lesson":1,"question":"I visited the gallery ____ I love modern art.","answers":["because","so","although","but"],"correct":0,"explanation":"Because introduces the reason."},{"id":"u4q47","unit":4,"lesson":1,"question":"The painting was bright, ____ everyone noticed it.","answers":["because","so","although","but"],"correct":1,"explanation":"So introduces the result."},{"id":"u4q48","unit":4,"lesson":1,"question":"The sculpture was heavy, ____ it looked elegant.","answers":["because","so","but","although"],"correct":2,"explanation":"But joins contrasting main ideas."},{"id":"u4q49","unit":4,"lesson":2,"question":"____ the museum was crowded, we enjoyed the visit.","answers":["Although","So","Because","But"],"correct":0,"explanation":"Although introduces a contrast."},{"id":"u4q50","unit":4,"lesson":2,"question":"Artists use imagination to ____ ideas.","answers":["express","block","store","reduce"],"correct":0,"explanation":"Artists express ideas through art."},{"id":"u4q51","unit":4,"lesson":2,"question":"A place where artworks are displayed is a ____.","answers":["gallery","password","highway","continent"],"correct":0,"explanation":"Gallery = place for displaying art."},{"id":"u4q52","unit":4,"lesson":3,"question":"The article ____ the artist’s early life.","answers":["describes","description","describing","describe"],"correct":0,"explanation":"Third-person singular subject + Present Simple."},{"id":"u4q53","unit":4,"lesson":3,"question":"The artist received international ____.","answers":["recognition","traffic","privacy","calmness"],"correct":0,"explanation":"Recognition = public appreciation/acknowledgment."},{"id":"u4q54","unit":4,"lesson":3,"question":"A person who creates art is an ____.","answers":["artist","inventor","athlete","guardian"],"correct":0,"explanation":"Artist is the correct noun."},{"id":"u4q55","unit":4,"lesson":4,"question":"The performance was long, ____ it never felt boring.","answers":["because","so","but","although"],"correct":2,"explanation":"But signals contrast."},{"id":"u4q56","unit":4,"lesson":4,"question":"I liked the show ____ the message was meaningful.","answers":["because","so","but","although"],"correct":0,"explanation":"Because explains why."},{"id":"u4q57","unit":4,"lesson":4,"question":"____ the actor was nervous, he performed well.","answers":["Although","So","Because","But"],"correct":0,"explanation":"Although shows contrast."},{"id":"u4q58","unit":4,"lesson":5,"question":"Art can bring people ____ and start conversations.","answers":["together","apart","offline","private"],"correct":0,"explanation":"“Bring people together” is a common expression."},{"id":"u4q59","unit":4,"lesson":5,"question":"The artist used clay ____ the sculpture.","answers":["for","at","from","on"],"correct":0,"explanation":"“Used for” expresses purpose."},{"id":"u4q60","unit":4,"lesson":5,"question":"Choose the best review opening.","answers":["I thought the performance was impressive because…","Yesterday is blue.","A password should be kept.","The road was blocked."],"correct":0,"explanation":"A review gives an opinion and supports it."},{"id":"u5q61","unit":5,"lesson":1,"question":"Egypt is ____ than some countries, but it has many famous landmarks.","answers":["old","older","oldest","more old"],"correct":1,"explanation":"Short adjective comparative = -er + than."},{"id":"u5q62","unit":5,"lesson":1,"question":"This destination is ____ than I expected.","answers":["impressive","more impressive","most impressive","the impressive"],"correct":1,"explanation":"Long adjective comparative = more + adjective + than."},{"id":"u5q63","unit":5,"lesson":1,"question":"Which is ____ place to visit in your list?","answers":["the most exciting","more exciting","exciting","the exciting"],"correct":0,"explanation":"Superlative needs “the most” for a long adjective."},{"id":"u5q64","unit":5,"lesson":2,"question":"The city center is ____ than the village.","answers":["busy","busier","busiest","more busy"],"correct":1,"explanation":"Busy → busier."},{"id":"u5q65","unit":5,"lesson":2,"question":"Cairo is one of the ____ cities in the region.","answers":["largest","larger","large","more large"],"correct":0,"explanation":"Superlative of large = largest."},{"id":"u5q66","unit":5,"lesson":2,"question":"A tour guide can make a visit ____ organized.","answers":["more","most","many","much"],"correct":0,"explanation":"“More organized” is the comparative form."},{"id":"u5q67","unit":5,"lesson":3,"question":"Mount Fuji is ____ than many nearby hills.","answers":["high","higher","highest","more high"],"correct":1,"explanation":"Short adjective comparative = higher."},{"id":"u5q68","unit":5,"lesson":3,"question":"This is the ____ museum I have visited.","answers":["most impressive","more impressive","impressive","impress"],"correct":0,"explanation":"Superlative = the most impressive."},{"id":"u5q69","unit":5,"lesson":3,"question":"Good → ____ → the best.","answers":["better","gooder","more good","best"],"correct":0,"explanation":"Good has an irregular comparative: better."},{"id":"u5q70","unit":5,"lesson":4,"question":"The trail is ____ than I thought, but it is beautiful.","answers":["longer","longest","more long","the longer"],"correct":0,"explanation":"Long → longer."},{"id":"u5q71","unit":5,"lesson":4,"question":"This adventure is ____ than the last one.","answers":["less dangerous","least dangerous","dangerous","the less dangerous"],"correct":0,"explanation":"Comparative can use less + adjective."},{"id":"u5q72","unit":5,"lesson":4,"question":"Which phrase is correct?","answers":["the most unforgettable","most unforgettable","the more unforgettable","unforgettableest"],"correct":0,"explanation":"Superlative with a long adjective uses the most."},{"id":"u5q73","unit":5,"lesson":5,"question":"Petra is famous for its ____ carvings and history.","answers":["ancient","ancienter","most ancienter","more ancienter"],"correct":0,"explanation":"Ancient is an adjective; no comparison is needed here."},{"id":"u5q74","unit":5,"lesson":5,"question":"A calm place may be ____ for relaxation than a noisy one.","answers":["better","best","good","the best"],"correct":0,"explanation":"Better is the comparative of good."},{"id":"u5q75","unit":5,"lesson":5,"question":"The Nile is one of the ____ rivers in the world.","answers":["longest","longer","long","most long"],"correct":0,"explanation":"Superlative of long = longest."},{"id":"u6q76","unit":6,"lesson":1,"question":"If I finish the model today, I ____ it tomorrow.","answers":["show","will show","would show","showed"],"correct":1,"explanation":"First Conditional: if + Present Simple, will + base verb."},{"id":"u6q77","unit":6,"lesson":1,"question":"If the idea works, we ____ improve it.","answers":["will","would","did","were"],"correct":0,"explanation":"First Conditional result uses will."},{"id":"u6q78","unit":6,"lesson":1,"question":"If it doesn’t work, we ____ try again.","answers":["will","would","were","are"],"correct":0,"explanation":"The likely future result uses will."},{"id":"u6q79","unit":6,"lesson":2,"question":"If I had more time, I ____ build a robot.","answers":["will","would","am","did"],"correct":1,"explanation":"Second Conditional uses would for an imaginary situation."},{"id":"u6q80","unit":6,"lesson":2,"question":"If I were you, I ____ keep trying.","answers":["will","would","did","am"],"correct":1,"explanation":"“If I were you, I would…” is a common advice pattern."},{"id":"u6q81","unit":6,"lesson":2,"question":"If she practiced more, she ____ improve quickly.","answers":["would","will","is","did"],"correct":0,"explanation":"Imaginary condition + would."},{"id":"u6q82","unit":6,"lesson":3,"question":"A person who creates useful new ideas is an ____.","answers":["innovator","tour guide","artist","guardian"],"correct":0,"explanation":"Innovator = a person who introduces useful new ideas."},{"id":"u6q83","unit":6,"lesson":3,"question":"Engineers use ____ to measure or detect things.","answers":["sensors","souvenirs","sculptures","mummies"],"correct":0,"explanation":"Sensors detect/measure changes."},{"id":"u6q84","unit":6,"lesson":3,"question":"A university teacher is often called a ____.","answers":["professor","soldier","blogger","athlete"],"correct":0,"explanation":"Professor = university teacher."},{"id":"u6q85","unit":6,"lesson":4,"question":"A biography tells the story of a person’s ____.","answers":["life","password","traffic","gallery"],"correct":0,"explanation":"Biography = account of a person’s life."},{"id":"u6q86","unit":6,"lesson":4,"question":"He was ____ in 1990.","answers":["born","birth","be born","borning"],"correct":0,"explanation":"The correct passive form is “was born”."},{"id":"u6q87","unit":6,"lesson":4,"question":"The biography should present events in a clear time ____.","answers":["order","impact","clay","code"],"correct":0,"explanation":"Chronological order organizes events by time."},{"id":"u6q88","unit":6,"lesson":5,"question":"If the team gets honest feedback, it ____ make the project better.","answers":["can","will","would","did"],"correct":1,"explanation":"Real future possibility: will can express the result."},{"id":"u6q89","unit":6,"lesson":5,"question":"If I could invent anything, I ____ create a water-saving device.","answers":["would","will","am","did"],"correct":0,"explanation":"Second Conditional expresses an imaginary idea."},{"id":"u6q90","unit":6,"lesson":5,"question":"Choose the best advice.","answers":["If I were you, I would keep testing the idea.","If I were you, I will stop.","If I am you, I would stop.","If I was you, I will stopping."],"correct":0,"explanation":"Correct advice pattern: If I were you, I would + base verb."}],"meta":{"sourceUnitOutline":"6-unit first-term Grade 8 outline.","videoSources":[{"unit":1,"youtube":"https://www.youtube.com/watch?v=ojNJUpYOZ98"},{"unit":2,"youtube":"https://www.youtube.com/watch?v=XbyVdsYv5VQ"},{"unit":3,"youtube":"https://www.youtube.com/watch?v=5s4M5cYA0Y4"},{"unit":4,"youtube":"https://www.youtube.com/watch?v=tUPxUDeRSPQ"},{"unit":5,"youtube":"https://www.youtube.com/watch?v=t87eq-pfbtI"},{"unit":6,"youtube":"https://www.youtube.com/results?search_query=الخطة+التعليمية+الثاني+الاعدادي+انجليزي+Unit+6+Young+Innovators"}]}};
  const STORAGE = 'trx_2prep_ultimate_v1';
  const USER_STORAGE = 'trx_2prep_user_v1';
  const SOUND_STORAGE = 'trx_2prep_sound_v1';
  const DEFAULT_STATE = {
    xp: 0,
    solved: 0,
    correct: 0,
    streak: 0,
    lastDate: null,
    completedLessons: [],
    mistakes: [],
    daily: { q: false, l: false, m: false },
    bossCount: 0,
    completedUnits: []
  };

  let state = loadState();
  let currentUser = loadUser();
  let soundOn = localStorage.getItem(SOUND_STORAGE) !== 'off';
  let selectedUnit = 1;
  let selectedLesson = 1;
  let lessonTab = 'overview';
  let quiz = null;
  let audioCtx = null;

  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];

  function loadState() {
    try { return normalizeState(JSON.parse(localStorage.getItem(STORAGE) || 'null') || DEFAULT_STATE); }
    catch { return normalizeState(DEFAULT_STATE); }
  }
  function normalizeState(s) {
    return {
      ...DEFAULT_STATE,
      ...s,
      completedLessons: Array.isArray(s.completedLessons) ? s.completedLessons : [],
      mistakes: Array.isArray(s.mistakes) ? s.mistakes : [],
      completedUnits: Array.isArray(s.completedUnits) ? s.completedUnits : [],
      daily: { ...DEFAULT_STATE.daily, ...(s.daily || {}) }
    };
  }
  function saveState(){ localStorage.setItem(STORAGE, JSON.stringify(state)); }
  function loadUser(){ try{return JSON.parse(localStorage.getItem(USER_STORAGE)||'null')}catch{return null} }
  function saveUser(user){currentUser=user;localStorage.setItem(USER_STORAGE,JSON.stringify(user));}
  function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function updateStreak(){
    const today=todayKey();
    if(!state.lastDate){state.streak=1;state.lastDate=today;saveState();return}
    if(state.lastDate===today) return;
    const old=new Date(state.lastDate); const now=new Date(today);
    const days=Math.round((now-old)/86400000);
    state.streak=days===1 ? state.streak+1 : 1;
    state.lastDate=today; saveState();
  }
  function initials(name){ return (name||'Student').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(); }
  function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
  function level(){return Math.floor(state.xp/100)+1}
  function levelXP(){return state.xp%100}
  function accuracy(){return state.solved?Math.round(state.correct/state.solved*100):0}
  function unitProgress(unit){
    const unitQs=COURSE.questions.filter(q=>q.unit===unit);
    const lessons=COURSE.lessons.find(x=>x.unit===unit)?.lessons || [];
    if(!lessons.length) return 0;
    const done=lessons.filter(l=>state.completedLessons.includes(l.id)).length;
    return Math.round(done/lessons.length*100);
  }
  function playTone(freq,duration=0.08,type='sine',volume=0.045,when=0){
    if(!soundOn) return;
    try{
      audioCtx = audioCtx || new (window.AudioContext||window.webkitAudioContext)();
      const o=audioCtx.createOscillator(), g=audioCtx.createGain();
      o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime+when);g.gain.exponentialRampToValueAtTime(0.0001,audioCtx.currentTime+when+duration);
      o.connect(g);g.connect(audioCtx.destination);o.start(audioCtx.currentTime+when);o.stop(audioCtx.currentTime+when+duration);
    }catch{}
  }
  function sound(name){
    if(!soundOn) return;
    if(name==='click') playTone(430,0.045,'sine',0.025);
    if(name==='correct'){playTone(660,0.08,'sine',0.04);playTone(880,0.11,'sine',0.035,0.08)}
    if(name==='wrong'){playTone(180,0.12,'triangle',0.035);playTone(130,0.12,'triangle',0.03,0.07)}
    if(name==='level'){playTone(523,0.08,'sine',0.04);playTone(659,0.08,'sine',0.04,0.08);playTone(784,0.14,'sine',0.04,0.16)}
    if(name==='win'){playTone(523,0.1,'sine',0.045);playTone(659,0.1,'sine',0.045,0.08);playTone(784,0.1,'sine',0.045,0.16);playTone(1046,0.25,'sine',0.045,0.24)}
  }
  function flashToast(text, kind=''){const t=document.createElement('div');t.className='toast '+kind;t.textContent=text;$('#toastStack').appendChild(t);setTimeout(()=>t.remove(),2600)}
  function playConfetti(){
    const host=$('#confetti');host.innerHTML='';
    for(let i=0;i<54;i++){const p=document.createElement('span');p.className='confetti-piece';p.style.left=Math.random()*100+'%';p.style.setProperty('--x',(Math.random()*220-110)+'px');p.style.animationDelay=(Math.random()*.45)+'s';p.style.background=['#6d4aff','#19b978','#ff9c3d','#3e84ff','#eb5573'][i%5];p.style.transform=`rotate(${Math.random()*80}deg)`;host.appendChild(p)}
  }
  function celebrate(title,text,xp,icon='🏆'){
    $('#celebrationIcon').textContent=icon;$('#celebrationTitle').textContent=title;$('#celebrationText').textContent=text;$('#celebrationXp').textContent=`+${xp} XP`;$('#celebration').classList.remove('hidden');playConfetti();sound('win');
  }
  function closeCelebration(){ $('#celebration').classList.add('hidden'); }

  function showApp(){
    $('#authScreen').classList.add('hidden');$('#app').classList.remove('hidden');
    updateStreak();renderAll();
  }
  function showAuth(){ $('#app').classList.add('hidden');$('#authScreen').classList.remove('hidden'); }
  function continueName(){
    const n=$('#studentName').value.trim();
    if(n.length<2){flashToast('Enter a name with at least 2 characters.','bad');return}
    saveUser({name:n,type:'name'});sound('click');showApp();
  }

  // Google Identity Services: optional, requires a real OAuth client ID in auth-config.js.
  function initGoogle(){
    const clientId=(window.AUTH_CONFIG&&window.AUTH_CONFIG.googleClientId)||'';
    const fallback=$('#googleFallback');
    if(!clientId){fallback.addEventListener('click',()=>flashToast('Add your Google Client ID in auth-config.js to enable real Google sign-in.','bad'));return;}
    if(!window.google?.accounts?.id) return;
    google.accounts.id.initialize({client_id:clientId,callback:credentialResponse,auto_select:false});
    google.accounts.id.renderButton($('#googleButtonWrap'),{theme:'outline',size:'large',shape:'pill',width:420,text:'continue_with'});
    fallback.classList.add('hidden');
  }
  function credentialResponse(resp){
    try{
      const payload=JSON.parse(atob(resp.credential.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));
      saveUser({name:payload.name||payload.given_name||'Student',email:payload.email||'',picture:payload.picture||'',type:'google'});sound('click');showApp();
    }catch{flashToast('Google sign-in could not be completed on this page.','bad')}
  }

  function navigate(page){
    sound('click');
    $$('.page').forEach(p=>p.classList.toggle('active',p.id===page));
    $$('.nav-item,.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
    const titles={dashboard:['Welcome back','Your learning hub for Term 1.'],units:['Units & Lessons','Follow the course one lesson at a time.'],grammar:['Grammar Master','Clear rules, clear examples, clear practice.'],practice:['Practice Lab','Solve, learn, improve.'],mistakes:['My Mistakes','Review the questions that caught you before.'],achievements:['Achievements','Build momentum and collect milestones.']};
    const t=titles[page]||titles.dashboard;$('#pageTitle').textContent=t[0];$('#pageSubtitle').textContent=t[1];window.scrollTo({top:0,behavior:'smooth'});
    if(page==='units')renderUnits(); if(page==='grammar')renderGrammar(); if(page==='mistakes')renderMistakes(); if(page==='achievements')renderAchievements(); if(page==='dashboard')renderDashboard();
  }

  function renderDashboard(){
    const name=currentUser?.name||'Student';
    $('#heroName').textContent=name.split(' ')[0];$('#avatar').textContent=initials(name);$('#topStreak').textContent=state.streak;
    $('#xpValue').textContent=state.xp;$('#accuracyValue').textContent=accuracy()+'%';$('#solvedValue').textContent=state.solved;$('#streakValue').textContent=state.streak;
    $('#missionQ').textContent=state.daily.q?'✓':'○';$('#missionL').textContent=state.daily.l?'✓':'○';$('#missionM').textContent=state.daily.m?'✓':'○';
    const done=Object.values(state.daily).filter(Boolean).length;$('#missionProgress').style.width=(done/3*100)+'%';$('#missionText').textContent=`${done} / 3 complete`;
    const host=$('#unitProgress');host.innerHTML=COURSE.units.map(u=>{const p=unitProgress(u.id);return `<div class="unit-progress-row"><div class="unit-progress-top"><span>Unit ${u.id} · ${escapeHtml(u.title)}</span><span>${p}%</span></div><div class="unit-track"><div style="width:${p}%"></div></div></div>`}).join('');
  }

  function renderUnits(){
    const host=$('#unitCards');
    host.innerHTML=COURSE.units.map(u=>{const p=unitProgress(u.id);return `<article class="unit-card" data-unit="${u.id}"><span class="unit-number">UNIT ${u.id}</span><h3>${escapeHtml(u.title)}</h3><p>${escapeHtml(u.subtitle)}</p><div class="unit-meta"><strong>${escapeHtml(u.grammarTitle)}</strong><span>${p}% complete</span></div><div class="unit-progress-mini"><div style="width:${p}%"></div></div></article>`}).join('');
    $$('.unit-card').forEach(c=>c.addEventListener('click',()=>openLessonView(Number(c.dataset.unit),1)));
    if(!$('#lessonView').classList.contains('hidden')) renderLessonView();
  }
  function openLessonView(unit,lesson){selectedUnit=unit;selectedLesson=lesson;lessonTab='overview';$('#lessonView').classList.remove('hidden');renderLessonView();$('#lessonView').scrollIntoView({behavior:'smooth',block:'start'});}
  function lessonData(unit,lesson){return COURSE.lessons.find(x=>x.unit===unit)?.lessons.find(x=>x.number===lesson)}
  function unitData(unit){return COURSE.units.find(u=>u.id===unit)}
  function lessonVideoSearch(u,l){return 'https://www.youtube.com/results?search_query='+encodeURIComponent(`الخطة التعليمية الثاني الإعدادي English Unit ${u} ${l}`)}
  function youtubeWatch(id){return `https://www.youtube.com/watch?v=${encodeURIComponent(id)}`}
  function youtubeEmbed(id){return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?rel=0&modestbranding=1`}
  function renderVideoBlock(u,l){
    const search=lessonVideoSearch(u.id,l.title);
    if(!u.videoId){
      return `<div class="learning-block lesson-video-card" style="grid-column:1/-1"><div class="video-head"><div><span class="eyebrow">WATCH & LEARN</span><h4>Lesson video</h4><p>No verified video ID is stored for this unit yet, so the site uses a safe YouTube search fallback instead of showing a broken player.</p></div><a class="btn btn-ghost video-open-btn" href="${search}" target="_blank" rel="noopener">Find on YouTube ↗</a></div><div class="video-fallback-card"><div class="video-fallback-icon">▶</div><h4>Search the lesson video</h4><p>${escapeHtml(l.title)}</p><a class="btn btn-primary" href="${search}" target="_blank" rel="noopener">Watch on YouTube</a></div><a class="video-search" href="${search}" target="_blank" rel="noopener">Find more videos for this lesson →</a></div>`;
    }
    const watch=youtubeWatch(u.videoId);
    return `<div class="learning-block lesson-video-card" style="grid-column:1/-1">
      <div class="video-head"><div><span class="eyebrow">WATCH & LEARN</span><h4>Related lesson video</h4><p>We show a safe preview first. If YouTube blocks embedded playback, the card stays usable and the YouTube button opens the original video.</p></div><div class="video-actions"><button class="btn btn-primary" data-play-video="${escapeHtml(u.videoId)}">▶ Play here</button><a class="btn btn-ghost video-open-btn" href="${watch}" target="_blank" rel="noopener">Open on YouTube ↗</a></div></div>
      <div class="video-wrap video-stage-shell" data-video-stage="${escapeHtml(u.videoId)}">
        <div class="video-preview">
          <img src="https://i.ytimg.com/vi/${encodeURIComponent(u.videoId)}/hqdefault.jpg" alt="Video thumbnail for ${escapeHtml(l.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" onerror="this.closest('.video-preview').classList.add('thumbnail-failed')">
          <div class="video-preview-overlay"><div class="video-play-circle">▶</div><div class="video-preview-title">${escapeHtml(u.videoTitle)}</div><div class="video-preview-sub">Click Play here or open the original YouTube video</div></div>
        </div>
      </div>
      <div class="video-fallback-bar"><span>⚡ Embedded playback may be restricted by YouTube.</span><a href="${watch}" target="_blank" rel="noopener">Open original video →</a></div>
      <p class="video-credit">${escapeHtml(u.videoTitle)}</p><a class="video-search" href="${search}" target="_blank" rel="noopener">Find more videos for “${escapeHtml(l.title)}” →</a>
    </div>`;
  }
  function bindVideoFallbacks(u,l){
    $$('[data-play-video]').forEach(btn=>btn.addEventListener('click',()=>{
      const id=btn.dataset.playVideo;
      const stage=document.querySelector(`[data-video-stage="${CSS.escape(id)}"]`);
      if(!stage)return;
      stage.innerHTML=`<iframe class="video-frame" src="${youtubeEmbed(id)}" title="${escapeHtml(u.videoTitle)}" loading="eager" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`;
      btn.disabled=true;
      btn.textContent='Playing in site';
      flashToast('Trying the in-site player. YouTube fallback is always available below.','good');
    }));
  }
  function renderLessonView(){
    const u=unitData(selectedUnit), l=lessonData(selectedUnit,selectedLesson); if(!u||!l)return;
    const done=state.completedLessons.includes(l.id);
    const videoBlock=renderVideoBlock(u,l);
    let body='';
    if(lessonTab==='overview') body=`<div class="learning-block"><h4>What you will learn</h4><p>${escapeHtml(l.description)}</p><div class="focus-tags" style="margin-top:10px">${l.focus.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div><button id="completeLesson" class="btn btn-primary complete-btn">${done?'✓ Lesson completed':'Mark lesson complete +15 XP'}</button></div><div class="learning-block"><h4>Why it matters</h4><p>This lesson is connected to the Unit ${u.id} topic and its core language focus. Read the notes, watch the video, then move to practice.</p><div class="grammar-section"><h4>Core grammar</h4><div class="formula">${escapeHtml(u.grammarTitle)}</div></div></div>${videoBlock}`;
    if(lessonTab==='video') body=videoBlock;
    if(lessonTab==='practice'){
      const qs=COURSE.questions.filter(q=>q.unit===u.id&&q.lesson===l.number);
      body=`<div class="learning-block" style="grid-column:1/-1"><h4>Lesson practice</h4><p>${qs.length} original practice questions are mapped to this lesson.</p><div style="display:grid;gap:8px;margin-top:10px">${qs.map(q=>`<button class="quick-row lesson-q" data-qid="${q.id}"><span>⚡</span><div><b>${escapeHtml(q.question)}</b><small>Choose one answer</small></div><i>→</i></button>`).join('')}</div></div>`;
    }
    $('#lessonView').innerHTML=`<div class="lesson-head"><div><div class="eyebrow">UNIT ${u.id} • LESSON ${l.number}</div><h2>${escapeHtml(l.title)}</h2><p>${escapeHtml(l.description)}</p></div><button class="close-btn" id="closeLesson">×</button></div><div class="lesson-tabs"><button class="lesson-tab ${lessonTab==='overview'?'active':''}" data-tab="overview">Overview</button><button class="lesson-tab ${lessonTab==='video'?'active':''}" data-tab="video">Video</button><button class="lesson-tab ${lessonTab==='practice'?'active':''}" data-tab="practice">Practice</button><a class="lesson-tab" href="${lessonVideoSearch(u.id,l.title)}" target="_blank" rel="noopener">More videos ↗</a></div><div class="lesson-body">${body}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:18px;font-size:10px;color:var(--muted)"><span>${done?'Completed ✓':'Not completed yet'}</span><span>Grammar: ${escapeHtml(u.grammarTitle)}</span></div>`;
    $$('.lesson-tab[data-tab]').forEach(b=>b.addEventListener('click',()=>{lessonTab=b.dataset.tab;renderLessonView()}));
    $('#closeLesson').addEventListener('click',()=>$('#lessonView').classList.add('hidden'));
    bindVideoFallbacks(u,l);
    const complete=$('#completeLesson');if(complete&&!done)complete.addEventListener('click',()=>completeLesson(l));
    $$('.lesson-q').forEach(b=>b.addEventListener('click',()=>startQuiz('Lesson Practice',[COURSE.questions.find(q=>q.id===b.dataset.qid)],'Lesson Practice')));
  }
  function completeLesson(l){
    if(state.completedLessons.includes(l.id))return;
    state.completedLessons.push(l.id);state.daily.l=true;state.xp+=15;
    const u=selectedUnit; if(unitProgress(u)>=100&&!state.completedUnits.includes(u)){state.completedUnits.push(u);state.xp+=40;sound('level');}
    saveState();renderDashboard();renderUnits();renderAchievements();renderLessonView();flashToast('Lesson complete — +15 XP!','good');
  }

  function renderGrammar(){
    $('#grammarCards').innerHTML=COURSE.units.map(u=>{const g=u.grammar;return `<article class="grammar-card"><div class="grammar-unit">UNIT ${u.id} • ${escapeHtml(u.title)}</div><h3>${escapeHtml(u.grammarTitle)}</h3><div class="grammar-section"><h4>1. What is it for?</h4><p>${escapeHtml(g.why)}</p></div><div class="grammar-section"><h4>2. The formula</h4><div class="formula">${escapeHtml(g.formula)}</div></div><div class="grammar-section"><h4>3. Negative</h4><p>${escapeHtml(g.negative)}</p></div><div class="grammar-section"><h4>4. Questions</h4><p>${escapeHtml(g.question)}</p></div><div class="grammar-section"><h4>5. Signal words</h4><div class="focus-tags">${g.signals.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div></div><div class="grammar-section"><h4>6. Teacher examples</h4><div class="example-grid">${g.examples.map(e=>`<div class="example"><b>${escapeHtml(e[0])}</b><span>${escapeHtml(e[1])}</span></div>`).join('')}</div></div><div class="grammar-section"><h4>7. Watch out</h4>${g.traps.map(t=>`<div class="trap">${escapeHtml(t)}</div>`).join('')}</div><div class="grammar-practice"><span>Test this grammar immediately.</span><button class="btn btn-primary" data-grammar-unit="${u.id}">Practice Unit ${u.id}</button></div></article>`}).join('');
    $$('[data-grammar-unit]').forEach(b=>b.addEventListener('click',()=>{const unit=Number(b.dataset.grammarUnit);startQuiz('Grammar Practice',COURSE.questions.filter(q=>q.unit===unit),'Grammar Practice')}));
  }

  function renderMistakes(){
    const host=$('#mistakesList');
    if(!state.mistakes.length){host.innerHTML='<div class="empty-state"><span class="emoji">🎯</span><h3>No mistakes saved yet.</h3><p>Answer a few practice questions and your incorrect answers will appear here.</p></div>';return}
    const seen=[]; state.mistakes.forEach(q=>{if(!seen.some(x=>x.id===q.id))seen.push(q)});
    host.innerHTML=seen.map(q=>`<div class="mistake-item"><div class="mistake-meta">UNIT ${q.unit} · LESSON ${q.lesson}</div><h3>${escapeHtml(q.question)}</h3><div class="mistake-options">${q.answers.map((a,i)=>`${String.fromCharCode(65+i)}. ${escapeHtml(a)}`).join(' · ')}</div><div class="mistake-answer">Correct answer: ${escapeHtml(q.answers[q.correct])}</div><button class="retry-btn" data-retry="${q.id}">Retry this question</button></div>`).join('');
    $$('[data-retry]').forEach(b=>b.addEventListener('click',()=>startQuiz('Mistake Review',[state.mistakes.find(q=>q.id===b.dataset.retry)],'Mistake Review')));
  }

  function renderAchievements(){
    const list=[
      ['🎯','First Steps','Solve 1 question',state.solved>=1],['⚡','10 Solved','Solve 10 questions',state.solved>=10],['🧠','50 Solved','Solve 50 questions',state.solved>=50],['🔥','7-Day Flame','Reach a 7-day streak',state.streak>=7],['📚','Lesson Complete','Complete your first lesson',state.completedLessons.length>=1],['🏅','Unit Master','Complete one whole unit',state.completedUnits.length>=1],['👑','Boss Challenger','Finish a Boss Exam',state.bossCount>=1],['💎','Accuracy Ace','Reach 90% accuracy with 20+ questions',state.solved>=20&&accuracy()>=90]];
    $('#achievementGrid').innerHTML=list.map(a=>`<article class="achievement-card ${a[3]?'unlocked':''}"><div class="aicon">${a[0]}</div><h3>${a[1]}</h3><p>${a[2]}</p></article>`).join('');
  }

  // Difficulty is derived from the original question bank.
  // The labels are used only to filter the custom exam; they do not change the question text.
  function getQuestionDifficulty(q){
    if(q.difficulty) return String(q.difficulty).toLowerCase();
    const text=(q.question+' '+q.explanation+' '+q.answers.join(' ')).toLowerCase();
    const hardSignals=['if ','would ','although','passive','past participle','was/were','while','when ','comparative','superlative','modal','condition'];
    const mediumSignals=['am/is/are','do/does','did ','because','so ','but ','present','past','should','must','can ','will '];
    if(hardSignals.some(x=>text.includes(x))) return 'hard';
    if(mediumSignals.some(x=>text.includes(x))) return 'medium';
    return 'easy';
  }

  function filteredCustomPool(){
    const unit=$('#customUnit')?.value || 'all';
    const difficulty=$('#customDifficulty')?.value || 'all';
    let pool=COURSE.questions.slice();
    if(unit!=='all') pool=pool.filter(q=>q.unit===Number(unit));
    if(difficulty!=='all') pool=pool.filter(q=>getQuestionDifficulty(q)===difficulty);
    return pool;
  }

  function updateCustomCountOptions(){
    const select=$('#customCount');
    if(!select) return;
    const total=filteredCustomPool().length;
    const preferred=[5,10,15,20,30,40,50,60,90];
    const counts=preferred.filter(n=>n<=total);
    if(total && !counts.includes(total)) counts.push(total);
    counts.sort((a,b)=>a-b);
    select.innerHTML=counts.length ? counts.map(n=>`<option value="${n}">${n} questions</option>`).join('') : '<option value="0">No questions available</option>';
    const available=$('#customAvailable');
    if(available) available.textContent=total ? `${total} questions available for this selection.` : 'No questions match this selection.';
  }

  function pickQuestionPool(mode,unit,count,difficulty='all'){
    let pool=COURSE.questions.slice();
    if(unit!=='all')pool=pool.filter(q=>q.unit===Number(unit));
    if(difficulty!=='all')pool=pool.filter(q=>getQuestionDifficulty(q)===String(difficulty).toLowerCase());
    if(mode==='mistakes')pool=state.mistakes.slice();
    if(mode==='lesson')pool=pool.filter(()=>true);
    pool=shuffle(pool);
    return pool.slice(0,Math.min(Number(count)||10,pool.length));
  }
  function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
  function startQuiz(title,questions,mode='Quick Practice'){
    const valid=questions.filter(Boolean); if(!valid.length){flashToast('No questions are available for this mode yet.','bad');return}
    quiz={title,mode,questions:shuffle(valid),index:0,selected:false,score:0,xpEarned:0,startedAt:Date.now()};
    $('#examModal').classList.remove('hidden');renderQuiz();
  }
  function renderQuiz(){
    const q=quiz.questions[quiz.index];
    if(!q){finishQuiz();return}
    quiz.selected=false;
    $('#examModal').innerHTML=`<div class="modal-box"><div class="modal-top"><div><div class="eyebrow">${escapeHtml(quiz.mode)}</div><h2>${escapeHtml(quiz.title)}</h2></div><button class="close-btn" id="closeQuiz">×</button></div><div class="quiz-progress"><div style="width:${(quiz.index/quiz.questions.length)*100}%"></div></div><div class="quiz-meta"><span>${quiz.index+1} / ${quiz.questions.length}</span><span>Unit ${q.unit} · Lesson ${q.lesson} · ${getQuestionDifficulty(q).toUpperCase()}</span></div><div class="quiz-question">${escapeHtml(q.question)}</div><div class="answer-list">${q.answers.map((a,i)=>`<button class="answer-btn" data-answer="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(a)}</button>`).join('')}</div><div class="feedback" id="feedback"></div><div class="quiz-footer"><small>+10 XP for a correct answer</small><button class="btn btn-primary" id="nextQuiz" disabled>${quiz.index===quiz.questions.length-1?'Finish':'Next →'}</button></div></div>`;
    $('#closeQuiz').addEventListener('click',closeQuiz);$$('[data-answer]').forEach(b=>b.addEventListener('click',()=>selectQuizAnswer(Number(b.dataset.answer))));$('#nextQuiz').addEventListener('click',nextQuiz);
  }
  function selectQuizAnswer(i){
    if(quiz.selected)return;quiz.selected=true;const q=quiz.questions[quiz.index];const btns=$$('[data-answer]');const correct=i===Number(q.correct);btns.forEach(b=>b.disabled=true);btns[q.correct]?.classList.add('correct');
    if(correct){btns[i].classList.add('correct');quiz.score++;quiz.xpEarned+=10;state.correct++;state.xp+=10;$('#feedback').innerHTML='<strong>Correct! Great job. 🎉</strong>';sound('correct');}
    else {btns[i].classList.add('wrong');$('#feedback').textContent=`Not quite. ${q.explanation}`;sound('wrong');state.mistakes.push(q)}
    state.solved++; if(state.solved>=10)state.daily.q=true;saveState();renderDashboard();renderMistakes();renderAchievements();$('#nextQuiz').disabled=false;
  }
  function nextQuiz(){if(!quiz.selected)return;quiz.index++;renderQuiz()}
  function finishQuiz(){
    $('#examModal').innerHTML=`<div class="modal-box result-card"><button class="close-btn" id="closeResult" style="float:right">×</button><div class="result-score">${Math.round(quiz.score/quiz.questions.length*100)}%</div><div class="eyebrow">${escapeHtml(quiz.mode)}</div><h2>${quiz.score>=quiz.questions.length*.8?'Excellent work!':'Good effort — keep going!'}</h2><p>You answered ${quiz.score} correctly out of ${quiz.questions.length}.</p><div class="result-badges"><span>+${quiz.xpEarned} XP</span><span>${quiz.score}/${quiz.questions.length} correct</span><span>${state.solved} total solved</span></div><div style="margin-top:18px;display:flex;gap:9px;justify-content:center;flex-wrap:wrap"><button class="btn btn-primary" id="resultClose">Keep learning →</button></div></div>`;
    if(quiz.mode==='Boss Exam'){state.bossCount++;state.xp+=25;saveState();}
    renderDashboard();renderAchievements();
    const pct=Math.round(quiz.score/quiz.questions.length*100);
    if(pct===100){celebrate('PERFECT SCORE!','Every answer was correct. That was amazing! 🔥',quiz.xpEarned+(quiz.mode==='Boss Exam'?25:0),'🏆');sound('level');}
    else if(pct>=80){celebrate('Great work!','You nailed the exam. Keep the streak alive! 🎉',quiz.xpEarned+(quiz.mode==='Boss Exam'?25:0),'⭐')}
    else sound('win');
    $('#closeResult').addEventListener('click',closeQuiz);$('#resultClose').addEventListener('click',closeQuiz);
  }
  function closeQuiz(){quiz=null;$('#examModal').classList.add('hidden')}

  function bind(){
    document.addEventListener('click',e=>{
      const target=e.target.closest('button,[role="button"]');
      if(target && !target.disabled && !target.matches('.answer-btn')) sound('click');
    });
    $('#nameContinue').addEventListener('click',continueName);$('#studentName').addEventListener('keydown',e=>{if(e.key==='Enter')continueName()});$('#celebrationClose').addEventListener('click',closeCelebration);
    $$('.nav-item,.mobile-nav button').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
    $$('[data-page-jump]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.pageJump)));
    $$('.quick-row').forEach(b=>b.addEventListener('mouseenter',()=>sound('click')));
    $$('[data-practice]').forEach(b=>b.addEventListener('click',()=>{
      const mode=b.dataset.practice;
      if(mode==='quick')startQuiz('Quick Practice',pickQuestionPool('quick','all',10),'Quick Practice');
      if(mode==='custom'){
        const unit=$('#customUnit').value;
        const difficulty=$('#customDifficulty').value;
        const count=Number($('#customCount').value);
        const pool=pickQuestionPool('custom',unit,count,difficulty);
        if(!pool.length){flashToast('No questions match your selection. Try another difficulty or unit.','bad');return;}
        startQuiz(`Custom Exam — ${unit==='all'?'All Units':`Unit ${unit}`} — ${difficulty==='all'?'All Levels':difficulty[0].toUpperCase()+difficulty.slice(1)}`,pool,'Custom Exam');
      }
      if(mode==='boss')startQuiz('Boss Exam',pickQuestionPool('boss','all',30),'Boss Exam');
    }));
    $('#soundToggle').addEventListener('click',()=>{soundOn=!soundOn;localStorage.setItem(SOUND_STORAGE,soundOn?'on':'off');$('#soundState').textContent=soundOn?'On':'Off';$('#soundBadge').textContent=`Sound: ${soundOn?'On':'Off'}`;if(soundOn)sound('correct')});
    $('#customUnit').addEventListener('change',updateCustomCountOptions);
    $('#customDifficulty').addEventListener('change',updateCustomCountOptions);
    updateCustomCountOptions();
    $('#signOut').addEventListener('click',()=>{localStorage.removeItem(USER_STORAGE);showAuth();$('#studentName').value='';});
  }
  function renderSoundState(){$('#soundState').textContent=soundOn?'On':'Off';$('#soundBadge').textContent=`Sound: ${soundOn?'On':'Off'}`}
  function renderAll(){renderSoundState();renderDashboard();renderUnits();renderGrammar();renderMistakes();renderAchievements();navigate('dashboard')}
  function init(){bind();renderSoundState();initGoogle();if(currentUser)showApp();else showAuth();}
  document.addEventListener('DOMContentLoaded',init);
})();
